using CleanTag.Core;
using System.Diagnostics;
using System.Runtime.InteropServices;
using System.Text.Json;

internal static class StorageAnalysisChecks
{
    public static async Task RunAsync(string root, Func<string, Func<Task>, Task> test)
    {
        var scanner = new StandardStorageScanner(); string folder = Path.Combine(root, "storage-analysis"); Directory.CreateDirectory(folder);
        Task<StorageAnalysisSnapshot> Scan(string path, CancellationToken token = default) => scanner.ScanAsync(path, new(), null, token);
        static void Check(bool condition, string message) { if (!condition) throw new Exception(message); }
        await test("Analysis empty and nonexistent roots have explicit states", async () =>
        { var empty = await Scan(folder); Check(empty.Nodes.Count == 1 && empty.Nodes[0].Bytes == 0 && empty.Status == StorageScanStatus.Completed, "Empty"); Check((await Scan(Path.Combine(folder, "absent"))).Status == StorageScanStatus.Failed, "Missing reported complete"); });
        Directory.CreateDirectory(Path.Combine(folder, "İç klasör [1]"));
        await File.WriteAllBytesAsync(Path.Combine(folder, "large.mp4"), new byte[9000]);
        await File.WriteAllBytesAsync(Path.Combine(folder, "İç klasör [1]", "görüş.v2.PNG"), new byte[1000]);
        await File.WriteAllBytesAsync(Path.Combine(folder, "zero.txt"), []);
        await File.WriteAllBytesAsync(Path.Combine(folder, "download.crdownload"), new byte[200]);
        StorageAnalysisSnapshot snapshot = await Scan(folder);
        await test("Analysis includes temporary and zero files; Unicode hierarchy and extension sums are exact", () =>
        { Check(snapshot.Nodes[0].Bytes == 10200 && snapshot.Nodes[0].Files == 4 && snapshot.Nodes[0].Folders == 1, "Totals"); Check(snapshot.Extensions.Sum(e => e.Bytes) == 10200, "Extensions"); Check(snapshot.Extensions.Any(e => e.Extension == ".png"), "Case normalization"); var file = snapshot.Nodes.Single(n => n.Name == "görüş.v2.PNG"); Check(snapshot.GetPath(file.Id) == Path.Combine(folder, "İç klasör [1]", "görüş.v2.PNG"), "Path"); Check(snapshot.Nodes.All(n => n.AllocatedBytes == null), "Invented allocation"); return Task.CompletedTask; });
        await test("Squarified geometry is proportional deterministic bounded and nonoverlapping", () =>
        {
            double[] weights = [9000, 1000, 200, 0]; var a = TreemapLayoutEngine.Squarify(weights, new(0, 0, 900, 600)); var b = TreemapLayoutEngine.Squarify(weights, new(0, 0, 900, 600));
            Check(a.SequenceEqual(b), "Determinism");
            for (int i = 0; i < a.Length; i++) { Check(Math.Abs(a[i].Area - weights[i] / 10200 * 540000) < .001, "Proportion"); Check(a[i].X >= 0 && a[i].Y >= 0 && a[i].X + a[i].Width <= 900.0001 && a[i].Y + a[i].Height <= 600.0001, "Bounds"); for (int j = 0; j < i; j++) Check(Math.Min(a[i].X + a[i].Width, a[j].X + a[j].Width) <= Math.Max(a[i].X, a[j].X) + .0001 || Math.Min(a[i].Y + a[i].Height, a[j].Y + a[j].Height) <= Math.Max(a[i].Y, a[j].Y) + .0001, "Overlap"); }
            var map = TreemapLayoutEngine.Build(snapshot, 0, 900, 600); foreach (var tile in map.Tiles) Check(map.HitTest(tile.Bounds.X + tile.Bounds.Width / 2, tile.Bounds.Y + tile.Bounds.Height / 2)?.NodeId == tile.NodeId, "Hit"); Check(map.HitTest(-1, -1) == null, "Outside hit"); return Task.CompletedTask;
        });
        await test("Repeated analysis navigation and filters never rescan or mutate snapshot totals", () =>
        { var dir = snapshot.Nodes.Single(n => n.IsDirectory && n.Id > 0); for (int i = 0; i < 30; i++) Check(TreemapLayoutEngine.Build(snapshot, dir.Id, 500, 300).Tiles.Count == 1, "Drill"); Check(TreemapLayoutEngine.Build(snapshot, 0, 500, 300, filter: n => n.Extension == ".png").Tiles.Count == 1, "Filter"); Check(snapshot.Nodes[0].Bytes == 10200, "Mutated"); return Task.CompletedTask; });
        await test("Analysis cancellation publishes explicitly partial consistent aggregates", async () =>
        { using var cts = new CancellationTokenSource(); cts.Cancel(); var partial = await Scan(folder, cts.Token); Check(partial.Status == StorageScanStatus.Cancelled && partial.Nodes[0].Incomplete, "Cancellation"); Check(partial.Nodes[0].Bytes == partial.Nodes.Where(n => !n.IsDirectory).Sum(n => n.Length), "Partial sum"); });
        await test("Analysis detects stale, renamed and removed files before management", async () =>
        { var entry = snapshot.GetEntry(snapshot.Nodes.Single(n => n.Name == "large.mp4").Id); File.AppendAllText(entry.FullPath, "changed"); bool blocked = false; try { FileSafety.Validate(folder, entry); } catch (IOException) { blocked = true; } Check(blocked, "Changed allowed"); File.Move(entry.FullPath, entry.FullPath + ".renamed"); blocked = false; try { FileSafety.Validate(folder, entry); } catch (IOException) { blocked = true; } Check(blocked, "Missing allowed"); await Task.CompletedTask; });
        await test("Deep and thousand-file analysis stays iterative and sums correctly", async () =>
        { string large = Path.Combine(root, "storage-many"); Directory.CreateDirectory(large); for (int i = 0; i < 3000; i++) File.WriteAllBytes(Path.Combine(large, $"{i}.txt"), new byte[16]); string deep = large; for (int i = 0; i < 80; i++) { deep = Path.Combine(deep, "d"); Directory.CreateDirectory(deep); } File.WriteAllText(Path.Combine(deep, "leaf"), "x"); var many = await Scan(large); Check(many.Nodes[0].Files == 3001 && many.Nodes[0].Folders == 80 && many.Nodes[0].Bytes == 48001, "Large totals"); var map = TreemapLayoutEngine.Build(many, 0, 1200, 800); Check(map.Tiles.Count > 1000, "Density"); });
        await test("Analysis excludes junction traversal and does not modify catalog tags or folder sizes", async () =>
        {
            string link = Path.Combine(folder, "loop"); var process = Process.Start(new ProcessStartInfo("cmd.exe", $"/c mklink /J \"{link}\" \"{folder}\"") { CreateNoWindow = true, UseShellExecute = false, RedirectStandardOutput = true, RedirectStandardError = true }); await process!.WaitForExitAsync(); if (process.ExitCode != 0) throw new Exception("Junction fixture unavailable"); try { var result = await Scan(folder); Check(result.Status == StorageScanStatus.Warnings && result.IssueCount > 0 && result.Nodes.Count < 30, "Traversal loop"); } finally { Directory.Delete(link); }
            var catalog = new CatalogStore(Path.Combine(root, "storage-catalog", "catalog.sqlite")); await catalog.InitializeAsync(); await catalog.AddFolderAsync(folder); var item = (await catalog.SearchAsync(new(FoldersOnly: true))).Files.Single(); var tag = await catalog.SaveTagAsync("Preserved"); await catalog.ChangeTagsAsync([item.Id], [tag.Id], true); await Scan(folder); var unchanged = (await catalog.SearchAsync(new(FoldersOnly: true))).Files.Single(); Check(unchanged.Size == 0 && unchanged.Tags.Single().Id == tag.Id && (await catalog.GetSourcesAsync()).Count == 0, "Catalog changed");
        });
        await test("Hard-linked paths are logical appearances rather than invented physical recovery", async () =>
        { string hard = Path.Combine(folder, "hard.txt"); string source = Path.Combine(folder, "download.crdownload"); long before = (await Scan(folder)).Nodes[0].Bytes; Check(CreateHardLinkW(hard, source, 0), "Hard link fixture"); var result = await Scan(folder); Check(result.Nodes.Count(n => n.Name == "download.crdownload" || n.Name == "hard.txt") == 2 && result.Nodes[0].Bytes == before + 200, "Lost logical appearances"); Check(result.Nodes[0].AllocatedBytes == null, "Invented physical count"); });
        await test("Large sparse lengths use 64-bit logical totals", async () =>
        { string sparseRoot = Path.Combine(root, "storage-sparse"); Directory.CreateDirectory(sparseRoot); string path = Path.Combine(sparseRoot, "big.bin"); using (var stream = File.Create(path)) { Check(DeviceIoControl(stream.SafeFileHandle, 0x900C4, 0, 0, 0, 0, out _, 0), "Sparse fixture"); stream.SetLength(5L * 1024 * 1024 * 1024); } var result = await Scan(sparseRoot); Check(result.Nodes[0].Bytes == 5L * 1024 * 1024 * 1024, "Truncated logical length"); });
        await test("Native identity rejects replacement with identical size and timestamp", async () =>
        { string path = Path.Combine(folder, "identity.txt"); File.WriteAllText(path, "old"); var f = new FileInfo(path); var entry = new FileEntry(path, f.Length, f.LastWriteTimeUtc.Ticks) { NativeId = FileIdentity.TryRead(path) }; Check(entry.NativeId != null, "Identity unavailable"); File.Move(path, path + ".old"); File.WriteAllText(path, "new"); File.SetLastWriteTimeUtc(path, new DateTime(entry.ModifiedTicks, DateTimeKind.Utc)); bool blocked = false; try { FileSafety.Validate(folder, entry); } catch (IOException) { blocked = true; } Check(blocked, "Replacement accepted"); await Task.CompletedTask; });
        await test("Mid-enumeration cancellation returns bounded consistent partial data", async () =>
        { using var cts = new CancellationTokenSource(); var result = await scanner.ScanAsync(Path.Combine(root, "storage-many"), new(), new CallbackProgress(p => { if (p.Files > 0) cts.Cancel(); }), cts.Token); Check(result.Status == StorageScanStatus.Cancelled && result.Nodes[0].Incomplete && result.Nodes[0].Files < 3001, "Mid scan cancellation"); Check(result.Nodes[0].Bytes == result.Nodes.Where(n => !n.IsDirectory).Sum(n => n.Length), "Partial totals"); });
        await test("Explicit analysis registration adds only one item and keeps folder semantics", async () =>
        { var catalog = new CatalogStore(Path.Combine(root, "analysis-explicit", "catalog.sqlite")); await catalog.InitializeAsync(); var snap = await Scan(folder); var node = snap.Nodes.First(n => !n.IsDirectory && n.Length > 0 && !n.Incomplete); string id = await catalog.RegisterAnalysisEntryAsync(snap.GetEntry(node.Id)); Check((await catalog.SearchAsync(new())).Files.Count == 1 && (await catalog.GetSourcesAsync()).Count == 0, "Implicit source/descendants"); var tag = await catalog.SaveTagAsync("Analyzer"); await catalog.ChangeTagsAsync([id], [tag.Id], true); Check((await catalog.GetFileTagsAsync(id)).Count == 1, "Tag lost"); string dirId = await catalog.RegisterAnalysisEntryAsync(snap.GetEntry(0)); Check((await catalog.SearchAsync(new(FoldersOnly: true))).Files.Single().Size == 0, "Recursive folder bytes persisted"); File.WriteAllText(Path.Combine(folder, "mtime-change"), "x"); Check(await catalog.FindAnalysisItemIdAsync(snap.GetEntry(0) with { NativeId = FileIdentity.TryRead(folder) }) == dirId, "Folder tags hidden by timestamp"); });
        await test("Inaccessible directories are reported and do not produce a complete snapshot", async () =>
        { string denied = Path.Combine(folder, "denied"); Directory.CreateDirectory(denied); File.WriteAllText(Path.Combine(denied, "private-fixture"), "x"); string sid = "*" + System.Security.Principal.WindowsIdentity.GetCurrent().User!.Value; async Task Acl(params string[] args) { var start = new ProcessStartInfo("icacls.exe") { UseShellExecute = false, CreateNoWindow = true, RedirectStandardOutput = true, RedirectStandardError = true }; start.ArgumentList.Add(denied); foreach (string arg in args) start.ArgumentList.Add(arg); using var p = Process.Start(start)!; var stdout = p.StandardOutput.ReadToEndAsync(); var stderr = p.StandardError.ReadToEndAsync(); await p.WaitForExitAsync(); await Task.WhenAll(stdout, stderr); Check(p.ExitCode == 0, "Fixture ACL setup failed"); } try { await Acl("/deny", sid + ":(RD)"); var result = await Scan(folder); Check(result.Status == StorageScanStatus.Warnings && result.Nodes[0].Incomplete && result.Issues.Any(i => i.Path == denied), "Access failure hidden"); } finally { await Acl("/remove:d", sid); } });
        await test("Million-entry snapshots retain totals with bounded dense map and immutable inputs", () =>
        { const int count = 1000000; var nodes = new StorageNode[count + 1]; nodes[0] = new(0, -1, "root", true, 0, 0, 0, count, count, 0, false); for (int i = 1; i <= count; i++) nodes[i] = new(i, 0, i + ".bin", false, 1, 0, 0, 1, 1, 0, false); var snap = new StorageAnalysisSnapshot(folder, nodes, [], [], 0, StorageScanStatus.Completed, DateTime.UtcNow, TimeSpan.Zero, TimeSpan.Zero); nodes[1] = nodes[1] with { Length = 999 }; Check(snap.Nodes[1].Length == 1, "Mutable snapshot"); var map = TreemapLayoutEngine.Build(snap, 0, 1600, 900); Check(map.Tiles.Count > 1000 && map.Tiles.Count <= 12000 && map.Tiles.Any(t => t.Aggregate), "Rendering unbounded/sparse"); Check(Math.Abs(map.Tiles.Sum(t => t.RepresentedBytes) - count) < .01, "Grouped totals lost"); foreach (var tile in map.Tiles) { Check(double.IsFinite(tile.Bounds.Area) && tile.Bounds.Area >= 0, "Invalid geometry"); Check(map.HitTest(tile.Bounds.X + tile.Bounds.Width / 2, tile.Bounds.Y + tile.Bounds.Height / 2)?.NodeId == tile.NodeId, "Dense hit"); } return Task.CompletedTask; });
    }
    private sealed class CallbackProgress(Action<StorageScanProgress> callback) : IProgress<StorageScanProgress> { public void Report(StorageScanProgress value) => callback(value); }
    public static async Task BenchmarkAsync()
    {
        string parent = Path.Combine(AppContext.BaseDirectory, "benchmark-data"); string root = Path.Combine(parent, "storage-" + Guid.NewGuid().ToString("N")); Directory.CreateDirectory(root);
        var reports = new List<object>();
        try
        {
            foreach (int count in new[] { 100, 4000, 20000 })
            {
                string folder = Path.Combine(root, count.ToString()); Directory.CreateDirectory(folder); for (int i = 0; i < count; i++) { string child = Path.Combine(folder, (i % 40).ToString()); Directory.CreateDirectory(child); File.WriteAllBytes(Path.Combine(child, i + ".bin"), new byte[128]); }
                var scanner = new StandardStorageScanner(); var watch = Stopwatch.StartNew(); var snapshot = await scanner.ScanAsync(folder, new(), null, default); double total = watch.Elapsed.TotalMilliseconds;
                watch.Restart(); var map = TreemapLayoutEngine.Build(snapshot, 0, 1400, 800); double layout = watch.Elapsed.TotalMilliseconds;
                watch.Restart(); await FileScanner.ScanAsync(folder, null, default); double baseline = watch.Elapsed.TotalMilliseconds;
                using var cancelled = new CancellationTokenSource(); var task = scanner.ScanAsync(folder, new(ProgressIntervalMilliseconds:0), new CallbackProgress(p => { if (p.Files > 0 && !cancelled.IsCancellationRequested) { watch.Restart(); cancelled.Cancel(); } }), cancelled.Token); var partial = await task; double cancellation = watch.Elapsed.TotalMilliseconds;
                reports.Add(new { files = count, folders = 40, logicalBytes = snapshot.Nodes[0].Bytes, enumerationMs = snapshot.EnumerationTime.TotalMilliseconds, aggregationMs = snapshot.AggregationTime.TotalMilliseconds, totalMs = total, layoutMs = layout, visibleTiles = map.Tiles.Count, existingScannerMs = baseline, cancellationMs = cancellation, cancellationStatus = partial.Status.ToString(), filesBeforeCancellation = partial.Nodes[0].Files, processPeakBytes = Process.GetCurrentProcess().PeakWorkingSet64 });
            }
            Directory.CreateDirectory("work"); await File.WriteAllTextAsync("work/storage-benchmark.json", JsonSerializer.Serialize(new { at = DateTime.UtcNow, os = RuntimeInformation.OSDescription, runtime = RuntimeInformation.FrameworkDescription, processorCount = Environment.ProcessorCount, reports }, new JsonSerializerOptions { WriteIndented = true })); Console.WriteLine(await File.ReadAllTextAsync("work/storage-benchmark.json"));
        }
        finally { if (FileSafety.IsWithin(parent, root)) Directory.Delete(root, true); }
    }
    [DllImport("kernel32.dll", CharSet = CharSet.Unicode, SetLastError = true)][return: MarshalAs(UnmanagedType.Bool)] private static extern bool CreateHardLinkW(string file, string existing, nint security);
    [DllImport("kernel32.dll", SetLastError = true)][return: MarshalAs(UnmanagedType.Bool)] private static extern bool DeviceIoControl(Microsoft.Win32.SafeHandles.SafeFileHandle file, uint control, nint input, uint inputSize, nint output, uint outputSize, out uint returned, nint overlapped);
}
